 [HttpPost("legacy-credit-attributions")]public Task<IActionResult> AttributeLegacyCredit(LegacyCreditAttributionRequest r,CancellationToken t)=>Tx(async()=>
 {
  if(user.UserId is null)return Unauthorized();if(r.RequestId==Guid.Empty||r.NetAmount<0||r.TaxAmount<0||decimal.Round(r.NetAmount,2)!=r.NetAmount||decimal.Round(r.TaxAmount,2)!=r.TaxAmount||r.ServiceDate==default||string.IsNullOrWhiteSpace(r.Reference)||string.IsNullOrWhiteSpace(r.Reason))return BadRequest();
  var source=await Rows("select branch_id from finance_credit_notes where id=@credit and organization_id=@org and (@wide or branch_id=@branch)",c=>Add(c,"credit",r.CreditId),t);if(source.Count!=1)return NotFound();var branch=source[0].GetProperty("branch_id").GetGuid();var snapshot=JsonSerializer.Serialize(r);var existing=await Rows("select request_snapshot=cast(@snapshot as jsonb) matches from finance_legacy_credit_attributions where id=@id and organization_id=@org and (@wide or branch_id=@branch)",c=>{Add(c,"id",r.RequestId);Add(c,"snapshot",snapshot);},t);if(existing.Count>0)return existing[0].GetProperty("matches").GetBoolean()?Ok(new{id=r.RequestId,replayed=true}):Conflict(new{message="Attribution ID has different details."});
  await Exec("insert into finance_legacy_credit_attributions(id,credit_id,organization_id,branch_id,net_amount,tax_amount,service_date,reference,reason,request_snapshot,created_by) values(@id,@credit,@org,@target,@net,@tax,@day,@reference,@reason,cast(@snapshot as jsonb),@actor)",c=>{Add(c,"id",r.RequestId);Add(c,"credit",r.CreditId);Add(c,"target",branch);Add(c,"net",r.NetAmount);Add(c,"tax",r.TaxAmount);Add(c,"day",r.ServiceDate);Add(c,"reference",r.Reference.Trim());Add(c,"reason",r.Reason.Trim());Add(c,"snapshot",snapshot);},t);await Audit("LEGACY_CREDIT_ATTRIBUTION_SUBMITTED",r.RequestId,branch,t);return Created("",new{id=r.RequestId});
 },t);
 [HttpPost("legacy-credit-attributions/{id:guid}/approve")]public Task<IActionResult> ApproveLegacyAttribution(Guid id,CancellationToken t)=>Tx(async()=>
 {
  var sources=await Rows("select a.*,c.amount,l.currency from finance_legacy_credit_attributions a join finance_credit_notes c on c.id=a.credit_id join finance_invoice_ledger l on l.invoice_id=c.invoice_id and l.organization_id=c.organization_id where a.id=@id and a.organization_id=@org and (@wide or a.branch_id=@branch) for update of a",c=>Add(c,"id",id),t);if(sources.Count!=1)return NotFound();var source=sources[0];if(source.GetProperty("created_by").GetGuid()==user.UserId)return Conflict(new{message="Independent attribution approval required."});if(source.GetProperty("approved_by").ValueKind!=JsonValueKind.Null)return source.GetProperty("approved_by").GetGuid()==user.UserId?Ok(new{id,replayed=true}):Conflict(new{message="Attribution already reviewed."});var branch=source.GetProperty("branch_id").GetGuid();var authorities=await Rows("select id from finance_adjustment_authorities where organization_id=@org and branch_id=@target and reviewer_id=@actor and approved_by is not null and currency=@currency and maximum_amount>=@amount and (now() at time zone 'Europe/London')::date between valid_from and valid_to order by maximum_amount,id limit 1",c=>{Add(c,"target",branch);Add(c,"currency",source.GetProperty("currency").GetString());Add(c,"amount",source.GetProperty("amount").GetDecimal());},t);if(authorities.Count!=1)return Conflict(new{message="Approved adjustment authority must cover this legacy credit."});await Exec("update finance_legacy_credit_attributions set approved_by=@actor,approved_at=now(),authority_id=@authority where id=@id and organization_id=@org",c=>{Add(c,"id",id);Add(c,"authority",authorities[0].GetProperty("id").GetGuid());},t);await Audit("LEGACY_CREDIT_ATTRIBUTION_APPROVED",id,branch,t);return Ok(new{id,balanceChanged=false});
 },t);
