 [HttpPost("authorities")]
 public Task<IActionResult> CreateAuthority(AdjustmentAuthorityRequest r,CancellationToken t)=>Tx(async()=>
 {
  if(user.UserId is null)return Unauthorized();if(r.RequestId==Guid.Empty||r.ReviewerId==Guid.Empty||r.ValidFrom==default||r.ValidTo<r.ValidFrom||string.IsNullOrWhiteSpace(r.Reference)||!Money(r.MaximumAmount)||r.Currency.Length!=3||!r.Currency.All(char.IsAsciiLetter)||(!tenant.IsOrganizationWide&&r.BranchId!=tenant.BranchId))return BadRequest(new{message="Scoped reviewer, positive exact monetary limit, currency, dates and authority reference are required."});
  var existing=await Rows("select * from finance_adjustment_authorities where id=@id and organization_id=@org and (@wide or branch_id=@branch)",c=>Add(c,"id",r.RequestId),t);
  if(existing.Count>0){var x=existing[0];return x.GetProperty("branch_id").GetGuid()==r.BranchId&&x.GetProperty("reviewer_id").GetGuid()==r.ReviewerId&&x.GetProperty("maximum_amount").GetDecimal()==r.MaximumAmount&&x.GetProperty("currency").GetString()!.Trim()==r.Currency.ToUpperInvariant()&&x.GetProperty("valid_from").GetString()==r.ValidFrom.ToString("yyyy-MM-dd")&&x.GetProperty("valid_to").GetString()==r.ValidTo.ToString("yyyy-MM-dd")&&x.GetProperty("reference").GetString()==r.Reference.Trim()?Ok(new{id=r.RequestId,replayed=true}):Conflict(new{message="Authority request ID has different details."});}
  await Exec("insert into finance_adjustment_authorities(id,organization_id,branch_id,reviewer_id,currency,maximum_amount,valid_from,valid_to,reference,created_by) values(@id,@org,@target,@reviewer,@currency,@maximum,@start,@end,@reference,@actor)",c=>{Add(c,"id",r.RequestId);Add(c,"target",r.BranchId);Add(c,"reviewer",r.ReviewerId);Add(c,"currency",r.Currency.ToUpperInvariant());Add(c,"maximum",r.MaximumAmount);Add(c,"start",r.ValidFrom);Add(c,"end",r.ValidTo);Add(c,"reference",r.Reference.Trim());},t);
  await Audit("ADJUSTMENT_AUTHORITY_CREATED",r.RequestId,r.BranchId,t);return Created($"/api/phase1/finance/adjustments/authorities/{r.RequestId}",new{id=r.RequestId});
 },t);
 [HttpPost("authorities/{id:guid}/approve")]
 public Task<IActionResult> ApproveAuthority(Guid id,CancellationToken t)=>Tx(async()=>
 {
  await using var c=await Command("update finance_adjustment_authorities set approved_by=@actor,approved_at=now() where id=@id and organization_id=@org and (@wide or branch_id=@branch) and approved_by is null and created_by<>@actor and reviewer_id<>@actor returning branch_id",t);Add(c,"id",id);
  if(await c.ExecuteScalarAsync(t) is not Guid branch)return Conflict(new{message="Authority approval requires a third person distinct from its creator and beneficiary reviewer."});await Audit("ADJUSTMENT_AUTHORITY_APPROVED",id,branch,t);return Ok(new{id});
 },t);
 [HttpPost]
 public Task<IActionResult> Create(FinancialAdjustmentRequest r,CancellationToken t)=>Tx(async()=>
 {
  if(user.UserId is null)return Unauthorized();if(r.RequestId==Guid.Empty||r.Kind is not ("Credit" or "Refund" or "WriteOff")||!Money(r.Amount)||string.IsNullOrWhiteSpace(r.Reason)||string.IsNullOrWhiteSpace(r.Reference)||
   (r.Kind=="Credit"&&(r.NetAmount is null or <0||r.TaxAmount is null or <0||r.NetAmount+r.TaxAmount!=r.Amount||r.ServiceDate is null||decimal.Round(r.NetAmount.Value,2)!=r.NetAmount||decimal.Round(r.TaxAmount.Value,2)!=r.TaxAmount)))return BadRequest(new{message="Kind, exact positive amount, reason/reference and explicit credit net/tax/service date are required."});
  var invoice=await Invoice(r.InvoiceId,t);if(invoice is null)return NotFound();if(!invoice.Value.GetProperty("is_issued").GetBoolean())return Conflict(new{message="Only issued invoices can be adjusted."});
  var branch=invoice.Value.GetProperty("branch_id").GetGuid();var currency=invoice.Value.GetProperty("currency").GetString()!;var snapshot=JsonSerializer.Serialize(r);
  await using(var replay=await Command("select request_snapshot=cast(@snapshot as jsonb) from finance_adjustment_requests where id=@id and organization_id=@org and branch_id=@target",t)){Add(replay,"snapshot",snapshot);Add(replay,"id",r.RequestId);Add(replay,"target",branch);if(await replay.ExecuteScalarAsync(t) is bool match)return match?Ok(new{id=r.RequestId,replayed=true}):Conflict(new{message="Adjustment request ID has different details."});}
  await Exec("insert into finance_adjustment_requests(id,invoice_id,organization_id,branch_id,kind,amount,currency,reason,reference,net_amount,tax_amount,service_date,correction_reference,request_snapshot,submitted_by) values(@id,@invoice,@org,@target,@kind,@amount,@currency,@reason,@reference,@net,@tax,@service,@correction,cast(@snapshot as jsonb),@actor)",c=>{Add(c,"id",r.RequestId);Add(c,"invoice",r.InvoiceId);Add(c,"target",branch);Add(c,"kind",r.Kind);Add(c,"amount",r.Amount);Add(c,"currency",currency);Add(c,"reason",r.Reason.Trim());Add(c,"reference",r.Reference.Trim());Nullable(c,"net",r.NetAmount,DbType.Decimal);Nullable(c,"tax",r.TaxAmount,DbType.Decimal);Nullable(c,"service",r.ServiceDate,DbType.Date);Add(c,"correction",r.CorrectionReference?.Trim()??"");Add(c,"snapshot",snapshot);},t);
  await Audit("FINANCIAL_ADJUSTMENT_SUBMITTED",r.RequestId,branch,t);return Created($"/api/phase1/finance/adjustments/{r.RequestId}",new{id=r.RequestId,status="Submitted"});
 },t);
 [HttpPost("{id:guid}/review")]
 public Task<IActionResult> Review(Guid id,AdjustmentReviewRequest r,CancellationToken t)=>Tx(async()=>
 {
  if(r.Decision is not ("Approve" or "Reject")||string.IsNullOrWhiteSpace(r.Reason))return BadRequest(new{message="Decision and review reason are required."});
  var rows=await Rows("select * from finance_adjustment_requests where id=@id and organization_id=@org and (@wide or branch_id=@branch) for update",c=>Add(c,"id",id),t);if(rows.Count!=1)return NotFound();var request=rows[0];var invoiceId=request.GetProperty("invoice_id").GetGuid();var invoice=await Invoice(invoiceId,t);if(invoice is null)return NotFound();
  if(request.GetProperty("status").GetString()!="Submitted")return request.GetProperty("reviewed_by").GetGuid()==user.UserId&&request.GetProperty("review_reason").GetString()==r.Reason.Trim()&&((r.Decision=="Approve")== (request.GetProperty("status").GetString()=="Posted"))?Ok(new{id,replayed=true,status=invoice.Value.GetProperty("status").GetString()}):Conflict(new{message="Adjustment was already reviewed."});
  if(request.GetProperty("submitted_by").GetGuid()==user.UserId)return Conflict(new{message="A different person must review the adjustment."});
  var branch=request.GetProperty("branch_id").GetGuid();var kind=request.GetProperty("kind").GetString()!;var amount=request.GetProperty("amount").GetDecimal();Guid? authority=null;var posted=Guid.NewGuid();
  if(r.Decision=="Approve")
  {
   if(!invoice.Value.GetProperty("is_issued").GetBoolean())return Conflict(new{message="The invoice is no longer issued."});
   var authorities=await Rows("select id from finance_adjustment_authorities where organization_id=@org and branch_id=@target and reviewer_id=@actor and approved_by is not null and currency=@currency and maximum_amount>=@amount and (now() at time zone 'Europe/London')::date between valid_from and valid_to order by maximum_amount,id limit 1",c=>{Add(c,"target",branch);Add(c,"currency",request.GetProperty("currency").GetString());Add(c,"amount",amount);},t);if(authorities.Count!=1)return Conflict(new{message="No approved authority covers this reviewer's branch, currency and amount."});authority=authorities[0].GetProperty("id").GetGuid();
   var balance=await InvoiceBalance.Read(db,tenant.OrganizationId,invoiceId,invoice.Value.GetProperty("gross_amount").GetDecimal(),t);
   if((kind=="Refund"&&amount>balance.Paid)||(kind=="WriteOff"&&amount>balance.Outstanding)||(kind=="Credit"&&amount>balance.Gross-balance.Credits-balance.WriteOffs))return Conflict(new{message="Current invoice balance no longer supports the adjustment."});
  }
  await Exec("update finance_adjustment_requests set status=@status,reviewed_by=@actor,reviewed_at=now(),review_reason=@reason,authority_id=@authority,posted_record_id=@posted where id=@id and organization_id=@org",c=>{Add(c,"id",id);Add(c,"status",r.Decision=="Approve"?"Posted":"Rejected");Add(c,"reason",r.Reason.Trim());Nullable(c,"authority",authority,DbType.Guid);Nullable(c,"posted",r.Decision=="Approve"?posted:null,DbType.Guid);},t);
  if(r.Decision=="Approve")
  {
   var sql=kind=="Credit"?"insert into finance_credit_notes(id,invoice_id,organization_id,branch_id,amount,adjustment_request_id,credit_number,reason,issued_by,net_amount,tax_amount,service_date) select @posted,invoice_id,organization_id,branch_id,amount,id,'CRN-'||id::text,reason,@name,net_amount,tax_amount,service_date from finance_adjustment_requests where id=@id and organization_id=@org":kind=="Refund"?"insert into finance_refunds(id,invoice_id,organization_id,branch_id,amount,adjustment_request_id,reference,reason,refunded_by) select @posted,invoice_id,organization_id,branch_id,amount,id,reference,reason,@name from finance_adjustment_requests where id=@id and organization_id=@org":"insert into finance_write_offs(id,invoice_id,organization_id,branch_id,amount,adjustment_request_id) select @posted,invoice_id,organization_id,branch_id,amount,id from finance_adjustment_requests where id=@id and organization_id=@org";
   await Exec(sql,c=>{Add(c,"posted",posted);Add(c,"id",id);Add(c,"name",user.UserName);},t);
   await Audit(kind=="Credit"?"finance.credit_note_issued":kind=="Refund"?"finance.refund_recorded":"finance.write_off_posted",posted,branch,t);
   var current=await InvoiceBalance.Read(db,tenant.OrganizationId,invoiceId,invoice.Value.GetProperty("gross_amount").GetDecimal(),t);await Exec("update \"Invoices\" set \"Status\"=@status where \"Id\"=@invoice and \"OrganizationId\"=@org",c=>{Add(c,"status",current.Status);Add(c,"invoice",invoiceId);},t);
  }
  await Audit(r.Decision=="Approve"?"FINANCIAL_ADJUSTMENT_POSTED":"FINANCIAL_ADJUSTMENT_REJECTED",id,branch,t);var final=await Invoice(invoiceId,t);return Ok(new{id,status=final!.Value.GetProperty("status").GetString(),postedRecordId=r.Decision=="Approve"?(Guid?)posted:null});
 },t);
 [HttpGet("disputes")]public async Task<IActionResult> Disputes(CancellationToken t)=>Ok(await Rows("select * from finance_invoice_disputes where organization_id=@org and (@wide or branch_id=@branch) order by created_at desc",_=>{},t));
 [HttpPost("disputes")]
 public Task<IActionResult> Dispute(InvoiceDisputeRequest r,CancellationToken t)=>Tx(async()=>
 {
  if(user.UserId is null)return Unauthorized();if(r.RequestId==Guid.Empty||!Money(r.Amount)||string.IsNullOrWhiteSpace(r.Reason)||string.IsNullOrWhiteSpace(r.EvidenceReference))return BadRequest(new{message="Request ID, amount, reason and evidence reference are required."});var invoice=await Invoice(r.InvoiceId,t);if(invoice is null)return NotFound();var branch=invoice.Value.GetProperty("branch_id").GetGuid();
  var existing=await Rows("select * from finance_invoice_disputes where id=@id and organization_id=@org and branch_id=@target",c=>{Add(c,"id",r.RequestId);Add(c,"target",branch);},t);if(existing.Count>0){var x=existing[0];return x.GetProperty("invoice_id").GetGuid()==r.InvoiceId&&x.GetProperty("amount").GetDecimal()==r.Amount&&x.GetProperty("reason").GetString()==r.Reason.Trim()&&x.GetProperty("evidence_reference").GetString()==r.EvidenceReference.Trim()?Ok(new{id=r.RequestId,replayed=true}):Conflict(new{message="Dispute ID has different details."});}
  await Exec("insert into finance_invoice_disputes(id,invoice_id,organization_id,branch_id,amount,reason,evidence_reference,created_by) values(@id,@invoice,@org,@target,@amount,@reason,@evidence,@actor)",c=>{Add(c,"id",r.RequestId);Add(c,"invoice",r.InvoiceId);Add(c,"target",branch);Add(c,"amount",r.Amount);Add(c,"reason",r.Reason.Trim());Add(c,"evidence",r.EvidenceReference.Trim());},t);await Audit("INVOICE_DISPUTE_OPENED",r.RequestId,branch,t);return Created($"/api/phase1/finance/adjustments/disputes/{r.RequestId}",new{id=r.RequestId,status="Open",balanceChanged=false});
 },t);
 [HttpPost("disputes/{id:guid}/resolve")]
 public Task<IActionResult> Resolve(Guid id,BillingContractDecision r,CancellationToken t)=>Tx(async()=>
 {
  if(string.IsNullOrWhiteSpace(r.Reason))return BadRequest(new{message="Resolution is required."});await using var c=await Command("update finance_invoice_disputes set status='Resolved',resolved_by=@actor,resolved_at=now(),resolution=@reason where id=@id and organization_id=@org and (@wide or branch_id=@branch) and status='Open' returning branch_id",t);Add(c,"id",id);Add(c,"reason",r.Reason.Trim());if(await c.ExecuteScalarAsync(t) is not Guid branch)return Conflict(new{message="Only an accessible open dispute can be resolved."});await Audit("INVOICE_DISPUTE_RESOLVED",id,branch,t);return Ok(new{id,status="Resolved",balanceChanged=false});
 },t);
 async Task<JsonElement?> Invoice(Guid id,CancellationToken t){var rows=await Rows("select l.* from finance_invoice_ledger l join \"Invoices\" i on i.\"Id\"=l.invoice_id where l.invoice_id=@id and l.organization_id=@org and (@wide or l.branch_id=@branch) for update of i",c=>Add(c,"id",id),t);return rows.Count==1?rows[0]:null;}
 async Task<IActionResult> Tx(Func<Task<IActionResult>> action,CancellationToken t){try{return await db.Database.CreateExecutionStrategy().ExecuteAsync(async()=>{await using var tx=await db.Database.BeginTransactionAsync(t);await Exec("select pg_advisory_xact_lock(hashtextextended(@lock,0))",c=>Add(c,"lock",$"finance-adjustments:{tenant.OrganizationId}"),t);var result=await action();if(result is ObjectResult failure&&failure.StatusCode>=400){await tx.RollbackAsync(t);return result;}await tx.CommitAsync(t);return result;});}catch(Npgsql.PostgresException e)when(e.SqlState is "23514" or "23505"){return Conflict(new{message="Adjustment authority, balance, source or attribution conflicts with the current invoice. Reload before retrying."});}}
 async Task<List<JsonElement>> Rows(string sql,Action<DbCommand> bind,CancellationToken t){var rows=new List<JsonElement>();await using var c=await Command($"select row_to_json(q)::text from ({sql})q",t);bind(c);await using var r=await c.ExecuteReaderAsync(t);while(await r.ReadAsync(t))rows.Add(JsonSerializer.Deserialize<JsonElement>(r.GetString(0)));return rows;}
 async Task<int> Exec(string sql,Action<DbCommand> bind,CancellationToken t){await using var c=await Command(sql,t);bind(c);return await c.ExecuteNonQueryAsync(t);}
 async Task<DbCommand> Command(string sql,CancellationToken t){var n=db.Database.GetDbConnection();if(n.State!=ConnectionState.Open)await n.OpenAsync(t);var c=n.CreateCommand();c.Transaction=db.Database.CurrentTransaction?.GetDbTransaction();c.CommandText=sql;Add(c,"org",tenant.OrganizationId);Add(c,"branch",tenant.BranchId??Guid.Empty);Add(c,"wide",tenant.IsOrganizationWide);Add(c,"actor",user.UserId);return c;}
 static void Add(DbCommand c,string name,object? value){var p=c.CreateParameter();p.ParameterName=name;p.Value=value??DBNull.Value;c.Parameters.Add(p);}
 static void Nullable(DbCommand c,string name,object? value,DbType type){var p=c.CreateParameter();p.ParameterName=name;p.DbType=type;p.Value=value??DBNull.Value;c.Parameters.Add(p);}
 static bool Money(decimal value)=>value>0&&value<=9999999999.99m&&decimal.Round(value,2)==value;
 async Task Audit(string action,Guid id,Guid branch,CancellationToken t){db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),action,user.UserName,"FinancialAdjustment",id,DateTimeOffset.UtcNow,tenant.OrganizationId,branch));await db.SaveChangesAsync(t);}
}
public sealed record FinancialAdjustmentRequest(Guid RequestId,Guid InvoiceId,string Kind,decimal Amount,string Reason,string Reference,decimal? NetAmount=null,decimal? TaxAmount=null,DateOnly? ServiceDate=null,string? CorrectionReference=null);
public sealed record AdjustmentAuthorityRequest(Guid RequestId,Guid BranchId,Guid ReviewerId,string Currency,decimal MaximumAmount,DateOnly ValidFrom,DateOnly ValidTo,string Reference);
public sealed record AdjustmentReviewRequest(string Decision,string Reason);
public sealed record InvoiceDisputeRequest(Guid RequestId,Guid InvoiceId,decimal Amount,string Reason,string EvidenceReference);
public sealed record LegacyCreditAttributionRequest(Guid RequestId,Guid CreditId,decimal NetAmount,decimal TaxAmount,DateOnly ServiceDate,string Reference,string Reason);
